workflow-item.script:
var ipam = System.getModule("com.example.ipam");
var state = System.getModule("com.example.state");
// ipam.notCalledInComment(x) is a comment, not a call
var note = "ipam.notCalledInString(x) is text";
var hostName = inputProperties.get("resourceNames")[0];
var address = inputProperties.get("addresses")[0][0];
var endpoint = new Properties();
// clear a stale record first, then register with the v2 module
ipam.removeRecord(endpoint, hostName);
ipam = System.getModule("com.example.ipam.v2");
ipam.addRecord(endpoint, hostName, address);
var st = state;
st.saveHostState(hostName, JSON.stringify({ address: address }));
System.log("registered " + hostName);
